pragma solidity ^0.8.0;
contract ERC20 {
  mapping(address => uint256) private _balances;
  mapping(address => mapping(address => uint256)) private _allowances;
  uint256 private _totalSupply;
  string public name;
  string public symbol;
  uint8 public decimals = 18;
  function totalSupply() public view returns (uint256) { return _totalSupply; }
  function balanceOf(address account) public view returns (uint256) { return _balances[account]; }
  function transfer(address to, uint256 amount) public returns (bool) {
    _balances[msg.sender] -= amount;
    _balances[to] += amount;
    return true;
  }
}

pragma solidity ^0.8.0;
contract ERC721 {
  mapping(uint256 => address) private _owners;
  mapping(address => uint256) private _balances;
  function ownerOf(uint256 tokenId) public view returns (address) { return _owners[tokenId]; }
  function safeTransferFrom(address from, address to, uint256 tokenId) public {
    require(_owners[tokenId] == from);
    _owners[tokenId] = to;
  }
}

pragma solidity ^0.8.0;
contract Vault {
  mapping(address => uint256) public balances;
  function deposit() public payable { balances[msg.sender] += msg.value; }
  function withdraw(uint256 amount) public {
    require(balances[msg.sender] >= amount);
    (bool ok,) = msg.sender.call{value: amount}("");
    require(ok);
    balances[msg.sender] -= amount;
  }
}

pragma solidity ^0.8.0;
contract Admin {
  address public owner;
  modifier onlyOwner() { require(msg.sender == owner); _; }
  function setOwner(address newOwner) public onlyOwner { owner = newOwner; }
}

pragma solidity ^0.8.0;
library SafeMath {
  function add(uint256 a, uint256 b) internal pure returns (uint256) { return a + b; }
  function sub(uint256 a, uint256 b) internal pure returns (uint256) { require(b <= a); return a - b; }
  function mul(uint256 a, uint256 b) internal pure returns (uint256) { return a * b; }
}
